      effects.push({ type: "if", cond: { kind: "amountNow", amount: count, min: 1 }, effects: [{ type: "reflexive", body: { ...reflexive, text: `${yardManyWhen[1]}, where X is the number of cards exiled this way.` }, xAmount: count }] });
