    const orAll = /^(Destroy all (?:[a-z]+ )?(?:creatures|enchantments)|Destroy all lands) or all ((?:[a-z]+ )?(?:creatures|enchantments))$/.exec(s) ?? /^(~ deals \d+ damage to each [a-z]+ creature) or (~ deals \d+ damage to each [a-z]+ creature)$/.exec(s);
