    const gruesome = /^If a creature died this turn, instead that player reveals their hand, you choose (two|three) cards from it, then that player discards those cards\.?$/.exec(sentences[si + 1] ?? "");
    if (gruesome && /^Target (?:player|opponent) discards (?:two|three) cards$/.test(s)) {
      const plain = parseOne(s, ctx);
      const d = plain?.length === 1 ? plain[0] : undefined;
      if (d?.type !== "discard" || d.who.ref !== "target") return null;
      effects.push({ type: "if", cond: { kind: "state", cond: { kind: "creatureDied" } }, effects: [{ type: "lookAtHand", who: d.who, reveal: true }, { type: "takeFromHand", who: d.who, action: "discard", n: num(gruesome[1]!) }], otherwise: [d] });
      si++;
      continue;
    }
    // Monsoon: "tap all untapped Islands that player controls and ~ deals X damage to the player, where X is the number of
    // Islands tapped this way": those that became tapped.
    const monsoon = /^[Tt]ap all untapped ([A-Z][a-z]+) that player controls and ~ deals X damage to the player, where X is the number of ([A-Z][a-z]+) tapped this way$/.exec(s);
    if (monsoon && monsoon[1] === monsoon[2]) {
      const fx = parseOne(`Tap all untapped ${monsoon[1]} that player controls`, ctx);
      const dmg = parseOne("~ deals 1 damage to that player", ctx);
      if (fx?.length !== 1 || fx[0]!.type !== "tap" || dmg?.length !== 1 || dmg[0]!.type !== "damage") return null;
      effects.push({ ...fx[0]!, noteTapped: true }, { ...dmg[0]!, amount: { count: { kind: "tappedThisWay" } } });
      continue;
    }
    // Pulse of the Dross: "Then if that player has more cards in hand than you, return ~ to its owner's hand.": the target
    // player's hand and yours as it resolves, after the discard; the spell goes to its owner's hand instead of the graveyard
    // (CR 608.2n).
    if (/^(?:Then )?[Ii]f that player has more cards in hand than you, return ~ to its owner's hand$/.test(s)) {
      const prev = effects[effects.length - 1];
      if (prev?.type !== "takeFromHand" || prev.who.ref !== "target" || !opts.spell) return null;
      const theirs = { kind: "cardsInHand" as const, who: prev.who };
      const mine = { kind: "cardsInHand" as const, who: { ref: "you" as const } };
      effects.push({ type: "if", cond: { kind: "amountsCompare", a: { count: theirs }, atLeast: { count: mine, plus: 1 } }, effects: [{ type: "bounce", what: { ref: "self" } }] });
      continue;
    }
    // Angel's Trumpet: "tap all untapped creatures that player controls that didn't attack this turn. ~ deals damage to the
    // player equal to the number of creatures tapped this way.": those that became tapped, as with Monsoon (rulings: ones
    // already tapped aren't counted).
    if (/^[Tt]ap all untapped creatures that player controls that didn't attack this turn$/.test(s) && /^~ deals damage to the player equal to the number of creatures tapped this way\.?$/.test(sentences[si + 1] ?? "")) {
      const fx = parseOne(s, ctx);
      const dmg = parseOne("~ deals 1 damage to that player", ctx);
      if (fx?.length !== 1 || fx[0]!.type !== "tap" || dmg?.length !== 1 || dmg[0]!.type !== "damage") return null;
      effects.push({ ...fx[0]!, noteTapped: true }, { ...dmg[0]!, amount: { count: { kind: "tappedThisWay" } } });
      si++;
      continue;
    }
    // Rhystic Lightning: "~ deals 4 damage to any target unless that permanent's controller or that player pays {2}. If they
    // do, ~ deals 2 damage to the permanent or player.": that player decides as it resolves (rulings), one or the other.
    const rhystic = /^(~ deals (\d+) damage to any target) unless that permanent's controller or that player (pays (?:\{[^}]+\})+)$/.exec(s);
    const rhysticPaid = rhystic && /^If they do, ~ deals (\d+) damage to the permanent or player\.?$/.exec(sentences[si + 1] ?? "");
    if (rhystic && rhysticPaid) {
      const before = ctx.targets.length;
      const fx = parseOne(rhystic[1]!, ctx);
      const options = parsePunisherOptions(rhystic[3]!, ctx);
      if (fx?.length !== 1 || fx[0]!.type !== "damage" || !options || ctx.targets.length !== before + 1) return null;
      effects.push({ type: "punisher", who: { ref: "targetOrController", index: before }, options, mode: "ifNone", effects: fx, otherwise: [{ ...fx[0]!, amount: Number(rhysticPaid[1]) }], thenText: `~ deals ${rhystic[2]} damage to it (${rhysticPaid[1]} if you do)` });
      si++;
      continue;
    }
    // Soldevi Sage: "Draw three cards, then discard one of them": one of the cards just drawn.
    const ofDrawn = /^(?:[Tt]hen )?[Dd]iscard one of them$/.test(s) ? effects[effects.length - 1] : undefined;
    if (ofDrawn) {
      if (ofDrawn.type !== "draw" || ofDrawn.who.ref !== "you" || typeof ofDrawn.n !== "number" || ofDrawn.n < 2) return null;
      effects.push({ type: "discard", who: { ref: "you" }, n: 1, drawn: true });
      continue;
    }
    // Landslide: "Sacrifice any number of Mountains. ~ deals that much damage to target player or planeswalker.": one
    // damage for each Mountain sacrificed, as it resolves (rulings).
    // Last-Ditch Effort: "Sacrifice any number of creatures. ~ deals that much damage to any target." The same.
    const slide = /^Sacrifice any number of ([A-Z][a-z]+|creatures)$/.exec(s);
    const slideNext = sentences[si + 1]?.replace(/\.$/, "") ?? "";
    if (slide && /^~ deals that much damage to (?:target [a-z ]+|any target)$/.test(slideNext)) {
      const filter = pickFilter(slide[1]!);
      const fx = filter && parseOne(slideNext.replace("that much", "X"), ctx);
      if (!filter || filter.kind !== "object" || fx?.length !== 1 || fx[0]!.type !== "damage") return null;
      effects.push({ type: "pick", who: { ref: "you" }, filter, n: 1, action: "sacrifice", anyNumber: true }, ...replaceX(fx, { count: { kind: "sacrificedThisWayCount" } }));
      si++;
      continue;
    }
    // Renounce: "Sacrifice any number of permanents. You gain 2 life for each permanent sacrificed this way": chosen as it
    // resolves (rulings).
    const renounce = /^Sacrifice any number of (permanents|creatures|lands|artifacts)$/.exec(s);
    const lifeEach = renounce && /^You gain (\d+) life for each ([a-z]+) sacrificed this way\.?$/.exec(sentences[si + 1] ?? "");
    if (renounce && lifeEach && `${lifeEach[2]}s` === renounce[1]) {
      const filter = pickFilter(renounce[1]!);
      if (filter?.kind !== "object") return null;
      effects.push({ type: "pick", who: { ref: "you" }, filter, n: 1, action: "sacrifice", anyNumber: true }, { type: "gainLife", who: { ref: "you" }, n: { count: { kind: "sacrificedThisWayCount" }, times: Number(lifeEach[1]) } });
      si++;
      continue;
    }
    // Reprocess: "Sacrifice any number of artifacts, creatures, and/or lands. Draw a card for each permanent sacrificed this
    // way": any mix of those, chosen as it resolves (CR 701.21a), then one card for each.
    if (/^Sacrifice any number of artifacts, creatures, and\/or lands$/.test(s) && /^Draw a card for each permanent sacrificed this way\.?$/.test(sentences[si + 1] ?? "")) {
      const filter: TargetSpec = { kind: "object", types: ["Artifact", "Creature", "Land"], notTypes: [], notColors: [], text: "artifact, creature, or land" };
      effects.push({ type: "pick", who: { ref: "you" }, filter, n: 1, action: "sacrifice", anyNumber: true }, { type: "draw", who: { ref: "you" }, n: { count: { kind: "sacrificedThisWayCount" } } });
      si++;
      continue;
    }
    // The Hunger Tide Rises IV: "Sacrifice any number of creatures. Search your library and/or graveyard for a creature card
    // with mana value less than or equal to the number of creatures sacrificed this way ...": chosen as it resolves, the
    // search reading how many were sacrificed.
    if (renounce && renounce[1] === "creatures" && /^Search your library (?:and\/or graveyard )?for .+ with mana value less than or equal to the number of creatures sacrificed this way\b/.test(sentences[si + 1] ?? "")) {
      const filter = pickFilter(renounce[1]!);
      if (filter?.kind !== "object") return null;
      effects.push({ type: "pick", who: { ref: "you" }, filter, n: 1, action: "sacrifice", anyNumber: true });
      continue;
    }
    // Mana Seism: "Sacrifice any number of lands, then add that much {C}": one {C} for each land sacrificed.
    // Kylox, Visionary Inventor: "sacrifice any number of other creatures, then exile the top X cards of your library, where X
    // is their total power. You may cast any number of instant and/or sorcery spells from among the exiled cards without
    // paying their mana costs.": the power of each as it last existed (rulings), chosen as it resolves; the spells cast as
    // it resolves or never, timing ignored, an X as 0 (rulings, CR 608.2g, 107.3b); the others stay exiled.
    if (/^[Ss]acrifice any number of other creatures$/.test(s) && sentences[si + 1] === "Exile the top X cards of your library, where X is their total power" && sentences[si + 2]?.replace(/\.$/, "") === "You may cast any number of instant and/or sorcery spells from among the exiled cards without paying their mana costs") {
      const filter = pickFilter("creatures");
      if (filter?.kind !== "object") return null;
      const spells: TargetSpec = { kind: "card", types: ["Instant", "Sorcery"], notTypes: [], notColors: [], text: "instant or sorcery card" };
      effects.push({ type: "pick", who: { ref: "you" }, filter: { ...filter, notSource: true, text: `other ${filter.text}` }, n: 1, action: "sacrifice", anyNumber: true }, { type: "castFromAmong", who: { ref: "you" }, n: { count: { kind: "sacrificedThisWayTotalPower" } }, filter: spells, asSpell: true });
      si += 2;
      continue;
    }
    const seism = /^[Ss]acrifice any number of lands$/.test(s) && /^(?:[Tt]hen )?[Aa]dd that much \{C\}$/.test(sentences[si + 1]?.replace(/\.$/, "") ?? "");
    const anySac = /^(?:[Yy]ou may )?[Ss]acrifice any number of (other )?(.+)$/.exec(s);
    const thatMany = sentences[si + 1]?.replace(/\.$/, "").replace(/^If you do, /, "") ?? "";
    if (anySac && (seism || (/\bthat many\b/.test(thatMany) && !/\bthat many\b.*\bthat many\b/.test(thatMany)))) {
      const filter = pickFilter(anySac[2]!);
      if (!filter) return null;
      const before = ctx.targets.length;
      const next = seism ? [{ type: "addMana" as const, mana: "{C}", times: { count: { kind: "x" as const } } }] : parseOne(capital(thatMany.replace(/\bthat many\b/, "X")), ctx);
      if (!next || ctx.targets.length !== before) return null;
      effects.push({ type: "pick", who: { ref: "you" }, filter: anySac[1] ? { ...filter, notSource: true, text: `other ${filter.text}` } : filter, n: 1, action: "sacrifice", anyNumber: true }, ...replaceX(next, { count: { kind: "sacrificedThisWayCount" } }));
      si++;
      continue;
    }
    // Hellion Eruption: "Sacrifice all creatures you control, then create that many 4/4 red Hellion creature tokens": as many
    // as were sacrificed.
    if (/^[Ss]acrifice all [^.]+ you control$/.test(s) && /\bthat many\b/.test(thatMany) && !/\bthat many\b.*\bthat many\b/.test(thatMany) && /^[Cc]reate that many /.test(thatMany)) {
      const before = ctx.targets.length;
      const sac = parseOne(s, ctx);
      const next = sac && parseOne(capital(thatMany.replace(/\bthat many\b/, "X")), ctx);
      if (!sac || sac.length !== 1 || sac[0]!.type !== "sacrifice" || !next || ctx.targets.length !== before) return null;
      effects.push(...sac, ...replaceX(next, { count: { kind: "sacrificedThisWayCount" } }));
      si++;
      continue;
    }
    // Nahiri's Lithoforming: "Sacrifice X lands. For each land sacrificed this way, draw a card.": as many as it sacrificed
    // (fewer than X with fewer lands, rulings).
    const sacX = /^[Ss]acrifice X (lands|creatures|artifacts|permanents)$/.exec(s);
    const perSac = sacX ? new RegExp(`^For each ${sacX[1]!.replace(/s$/, "")} sacrificed this way, draw a card$`).test(sentences[si + 1]?.replace(/\.$/, "") ?? "") : false;
    if (sacX && perSac) {
      const filter = pickFilter(sacX[1]!);
      if (!filter) return null;
      effects.push({ type: "pick", who: { ref: "you" }, filter, n: { count: { kind: "x" } }, action: "sacrifice" }, { type: "draw", who: { ref: "you" }, n: { count: { kind: "sacrificedThisWayCount" } } });
      si++;
      continue;
    }
    // "Choose two target creature cards in your graveyard. Sacrifice a creature. If you do, return the chosen cards to the
    // battlefield tapped." (Victimize): the targets, chosen as it's cast (CR 601.2c); "the chosen cards" are them.
    const chooseCards = /^Choose ((?:two|three) target [a-z]+ cards) in your graveyard$/.exec(s);
    if (chooseCards) {
      const what = parseObject(`${chooseCards[1]} from your graveyard`, ctx, true);
      if (what?.ref !== "target" || !what.n) return null;
      chosenCards = what;
      continue;
    }
    // "Each player sacrifices a creature or planeswalker of their choice. Each player who can't discards a card."
    // (Plaguecrafter): those who had none to sacrifice, after the sacrifices (rulings).
    // Skull Storm: "Each opponent who can't loses half their life, rounded up": each of them, by their own life total.
    const cant = /^Each (player|opponent) who can't (?:discards (a card|two cards)|(loses half their life, rounded up))$/.exec(s);
    const pickPrev = effects[effects.length - 1];
    if (cant && pickPrev?.type === "pick" && pickPrev.action === "sacrifice" && pickPrev.who.ref === (cant[1] === "player" ? "eachPlayer" : "eachOpponent") && !pickPrev.unless) {
      effects.push(cant[3] ? { type: "loseLife", who: { ref: "couldntPick" }, n: { count: { kind: "life", who: { ref: "eachOne" } }, half: "up" } } : { type: "discard", who: { ref: "couldntPick" }, n: cant[2] === "a card" ? 1 : 2, random: false });
      continue;
    }
    // Transmute Artifact: "Search your library for an artifact card. If that card's mana value is less than or equal to the
    // sacrificed artifact's mana value, put it onto the battlefield. If it's greater, you may pay {X}, where X is the
    // difference. If you do, put it onto the battlefield. If you don't, put it into its owner's graveyard. Then shuffle."
    // One search; the {X} is paid as it resolves, after the card is found (rulings).
    const payDiff = /^If you do, (search your library for an? [A-Za-z ]+? card)$/.exec(s);
    const payPrev = effects[effects.length - 1];
    const payMv = payDiff && /^If that card's mana value is less than or equal to (the sacrificed (?:artifact|creature|enchantment|permanent)'s mana value), put it onto the battlefield$/.exec(sentences[si + 1] ?? "");
    if (payMv && payPrev?.type === "pick" && payPrev.action === "sacrifice" && payPrev.who.ref === "you" && payPrev.n === 1 && !payPrev.unless && sentences[si + 2] === "If it's greater, you may pay {X}, where X is the difference" && sentences[si + 3] === "If you do, put it onto the battlefield" && sentences[si + 4] === "If you don't, put it into its owner's graveyard" && /^Then,? shuffle$/.test(sentences[si + 5] ?? "")) {
      const fx = parseOne(`${capital(payDiff![1]!)}, put it onto the battlefield, then shuffle`, ctx);
      const mv = parseCount(payMv[1]!, ctx);
      if (!mv || fx?.length !== 1 || fx[0]!.type !== "search" || fx[0]!.n !== 1 || fx[0]!.upTo || fx[0]!.others) return null;
      effects.push({ type: "if", cond: { kind: "sacrificedThisWay" }, effects: [{ ...fx[0]!, payDiff: mv }] });
      si += 5;
      continue;
    }
    // "Search your library for a creature or land card and reveal it. Put it onto the battlefield tapped if it's a land
    // card. Otherwise, put it into your hand. Then shuffle." (Archdruid's Charm): one search, the land card's own destination.
    const searchReveal = /^Search your library for (an? [A-Za-z ]+? card) and reveal it$/.exec(s);
