    const aboutSelf = si > 0 && /^(?:~ (?:gets|gains|has|becomes)\b|[Pp]ut [^.]+ counters? on ~$)/.test(sentences[si - 1]!) && !/\b(?:target|it|them)\b/.test(sentences[si - 1]!);
